UPDATE risk_knowledge_entries SET problem_json='{"statement":"Predictable, long-lived, logged or broadly scoped sessions can be stolen or reused.","customer_symptom":"Users or administrators may observe sessions that remain active after logout, expire too late, survive privilege changes without rotation, or expose session identifiers in insecure storage, URLs or logs.","credible_failure_or_attack":"An attacker who predicts, fixes, obtains or reuses a session identifier can impersonate an authenticated user or retain access after logout, expiry, revocation or a privilege change.","affected_assets":["web control-plane user sessions","session identifiers, cookies and server-side session records","authenticated account and tenant scope","privileged administrative actions and evidence access"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["web control planes"],"threat_actor_or_failure_source":"session fixation, token theft or reuse, insecure cookie or browser storage, weak expiry or invalidation, and session-policy configuration error","trust_boundary":"The boundary between an unauthenticated or superseded session identifier and currently authorised account, tenant and privilege scope on the web control plane.","operational_impact":"If predictable, long-lived, logged or broadly scoped sessions can be stolen or reused, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-09","next_review_due":"2026-12-02","change_triggers":["ARL-KB-021 session-token, cookie, login, logout or session-storage change","ARL-KB-021 session lifetime, rotation, revocation or privilege-change behaviour change","ARL-KB-021 fixation, token leakage, session theft or continued-use incident","ARL-KB-021 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"owner-approved semantic correction; independent practitioner and customer validation required"}', content_digest='1f55ed3f530b7452c0eb115f59c758bd34613251a48d7ed1c98f31812ca77220', updated_at='2026-10-09' WHERE id='ARL-KB-021';
UPDATE risk_knowledge_checks SET objective='Determine whether web control-plane sessions are unpredictable, confidential, correctly scoped and protected against fixation, leakage, replay and continued use after timeout, logout, revocation or privilege changes.', method='Review the owner-approved session policy covering issuance, entropy, cookie/storage flags, idle and absolute lifetime, rotation, concurrent sessions, logout, revocation and role changes. Inspect server-side source/configuration and privacy-safe session metadata without storing raw tokens. With separate written owner authorisation, use synthetic identities in a bounded staging environment to verify valid session use and negative fixation, expired, logged-out, superseded, revoked, replayed and privilege-changed token scenarios; reconcile observed authentication/audit events with the exact assessed version and human-reviewed exceptions.', required_evidence_json='["ARL-KB-021 exact assessed system, version, environment, authenticated identity, tenant and session scope","ARL-KB-021 organisation-approved session policy covering issuance, idle and absolute expiry, secure cookies, storage, rotation, logout, revocation and privilege changes","ARL-KB-021 source or configuration evidence of session creation, cookie attributes, token storage, expiry, rotation and invalidation controls","ARL-KB-021 bounded positive evidence of authorised login, protected session attributes, scoped access and expected session rotation with observed authentication events","ARL-KB-021 bounded negative evidence that fixed, leaked, replayed, expired, logged-out, superseded or revoked session identifiers are rejected, including after privilege changes","ARL-KB-021 observed runtime authentication and session invalidation events tied to the tested identities and exact assessed version","ARL-KB-021 tester and reviewer identity, roles, timestamp, assessed version, scope, exception decision and evidence digest"]', pass_condition='ARL-KB-021 passes only if the approved policy and privacy-safe technical evidence apply to the exact assessed version; valid sessions have bounded scope, protected issuance and transport/storage and documented lifetime; authorised tests demonstrate rotation and timely invalidation; negative tests reject fixed, expired, logged-out, revoked, superseded or privilege-mismatched sessions before protected access; and attributable events, limitations and human review support the decision.', fail_condition='ARL-KB-021 fails or requires review if session identifiers can be fixed, predicted, exposed or reused outside approved lifetime or scope; if logout, revocation, privilege-change rotation or expiry can be bypassed; or if the policy, actual session configuration, bounded denial evidence or attributable review is missing or mismatched to the assessed version.', content_digest='4411d5d6080529c46f578e0ba02a588b3121af04804eec436127baf9deccd2cf', updated_at='2026-10-09' WHERE entry_id='ARL-KB-021';
UPDATE risk_knowledge_solutions SET retest_acceptance_json='["ARL-KB-021: Exact remediated version, approved session policy, cookie/storage/expiry configuration and evidence digest are recorded.","ARL-KB-021: Authorised synthetic sessions function with documented tenant, role, lifetime and rotation behaviour.","ARL-KB-021: Fixed, replayed, expired, logged-out, revoked and privilege-superseded identifiers are rejected with version-bound server events.","ARL-KB-021: Reviewer identity, exception decisions, limitations and exact-retest evidence are recorded."]', content_digest='8158c57c6cfebd1bef29ec2ec149af9ef06abc00a00cf5aeab3833abdce682bc', updated_at='2026-10-09' WHERE entry_id='ARL-KB-021';
